args.newString:
import { Playfair_Display, Roboto } from 'next/font/google'

const playfair = Playfair_Display({
  subsets: ['latin'],
  variable: '--font-playfair',
})

const roboto = Roboto({
  subsets: ['latin'],
  weight: ['400', '700'],
  variable: '--font-roboto',
})

export default function BlogHeader() {
  return (
    <header className={`${playfair.variable} ${roboto.variable}`}>
      <h1 className="font-[family-name:var(--font-playfair)]">My Personal Blog</h1>
      <p className="font-[family-name:var(--font-roboto)]">Thoughts, ideas, and musings</p>
    </header>
  )
}

